 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The solid colored edge is the platform; objects collect toward it.
    boundary = None
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            boundary = r
            break
    if boundary is None:
        raise ValueError('no solid boundary row')
    direction = -1 if boundary == 0 else 1

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen or r == boundary:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            objects.append((color, cells))

    # Process the objects nearest the platform first, preserving each shape.
    if direction > 0:
        objects.sort(key=lambda obj: max(r for r, _ in obj[1]), reverse=True)
    else:
        objects.sort(key=lambda obj: min(r for r, _ in obj[1]))
    occupied = {(boundary, c) for c in range(w)}
    shifted = []
    for color, cells in objects:
        current = set(cells)
        occupied.update(current)
        while True:
            moved = {(r + direction, c) for r, c in current}
            if any(r < 0 or r >= h or (r, c) in (occupied - current) for r, c in moved):
                break
            occupied.difference_update(current)
            current = moved
            occupied.update(current)
        shifted.append((color, current))

    out = [[0 for _ in range(w)] for _ in range(h)]
    for c in range(w):
        out[boundary][c] = grid[boundary][c]
    for color, cells in shifted:
        for r, c in cells:
            out[r][c] = color
    return out
